    pm.expect(pm.response.headers.get("Content-Type").toLowerCase()).to.include("text/xml");
});

pm.test("5. Response body is not empty", function () {
    pm.expect(pm.response.text()).to.not.be.empty;
});

pm.test("6. Response contains SOAP Envelope", function () {
    pm.expect(pm.response.text()).to.include("<soap:Envelope");
});

pm.test("7. Response contains SOAP Body", function () {
    pm.expect(pm.response.text()).to.include("<soap:Body>");
});

pm.test("8. Response contains IsValidISBN13Response", function () {
    const xml = xml2Json(pm.response.text());

    pm.expect(xml["soap:Envelope"]["soap:Body"])
        .to.have.property("m:IsValidISBN13Response");
});

pm.test("9. Response contains IsValidISBN13Result", function () {
    const xml = xml2Json(pm.response.text());

    const response =
        xml["soap:Envelope"]["soap:Body"]["m:IsValidISBN13Response"];

    pm.expect(response).to.have.property("m:IsValidISBN13Result");
});

pm.test("10. ISBN13 validation result is true", function () {
    const xml = xml2Json(pm.response.text());

    const result =
        xml["soap:Envelope"]["soap:Body"]
            ["m:IsValidISBN13Response"]
            ["m:IsValidISBN13Result"];

    pm.expect(result).to.equal("true");
});

